// Companion to GatewayLiveValidation.cs. Use the consumer fixture generated by
// Test-PackageImport.ps1 in Assets/GatewayLiveValidation/Consumer.
using System;
using System.IO;
using UnityEditor;
using UnityEngine;

[InitializeOnLoad]
public static class GatewayLiveConsumerValidation
{
    [Serializable] private class Result
    {
        public string unityVersion, timestampUtc, scope, status, consumerAssembly;
        public bool publicTypesPreserved;
    }

    static GatewayLiveConsumerValidation() { EditorApplication.delayCall += Validate; }

    private static void Validate()
    {
        string settingsPath = Path.GetFullPath(Path.Combine(Application.dataPath, "../Temp/GatewayLiveValidation/settings.json"));
        if (!File.Exists(settingsPath)) return;
        var settings = JsonUtility.FromJson<GatewayLiveValidation.Settings>(File.ReadAllText(settingsPath));
        var result = new Result { unityVersion = Application.unityVersion, timestampUtc = DateTime.UtcNow.ToString("o"), scope = "live-editor-custom-consumer-assembly-compilation", status = "passed", publicTypesPreserved = true };
        result.consumerAssembly = typeof(GatewayPackageConsumer).Assembly.GetName().Name;
        if (result.consumerAssembly != "Gateway.PackageConsumer" || GatewayPackageConsumer.PublicTypes.Length != 6) result.status = "failed";
        foreach (Type type in GatewayPackageConsumer.PublicTypes)
            if (type.Assembly.GetName().Name != "Muxy.Gateway") { result.status = "failed"; result.publicTypesPreserved = false; }
        File.WriteAllText(Path.Combine(settings.outputDirectory, "consumer-result.json"), JsonUtility.ToJson(result, true));
    }
}
